    content: "# HTTPS for selfhost: Caddy gets a certificate for SELFHOST_DOMAIN and serves the API (/v1), the\n# agents' OpenTelemetry endpoint (/otlp) and the console on ports 80 and 443. See Caddyfile.\n# Use it with COMPOSE_FILE=compose.yml:compose.tls.yml in .env, and set SELFHOST_BIND=127.0.0.1\n# and OTLP_BIND=127.0.0.1 there, so the API and the collector are not reachable from outside.\n# SELFHOST_DOMAIN must point at this server before Caddy can get the certificate.\nservices:\n  caddy:\n    image: caddy:2.11.9-alpine\n    restart: unless-stopped\n    depends_on:\n      selfhost:\n        condition: service_healthy\n    environment:\n      SELFHOST_DOMAIN: ${SELFHOST_DOMAIN:?Set SELFHOST_DOMAIN in .env}\n      # compose.signin.yml sets this to signin.\n      SELFHOST_CONSOLE_ACCESS: closed\n    ports:\n      - \"80:80\"\n      - \"443:443\"\n      - \"443:443/udp\"\n    volumes:\n      - ./Caddyfile:/etc/caddy/Caddyfile:ro\n      - ./console:/srv/console:ro\n      # Certificates and the ACME account. Losing them means asking for new certificates, which\n      # Let's Encrypt rate limits.\n      - caddy-data:/data\n      - caddy-config:/config\n    healthcheck:\n      test: [\"CMD\", \"wget\", \"-q\", \"-T\", \"4\", \"-O\", \"/dev/null\", \"http://127.0.0.1:2019/config/\"]\n      interval: 10s\n      timeout: 5s\n      retries: 5\n      start_period: 10s\n    logging:\n      driver: json-file\n      options:\n        max-size: 10m\n        max-file: \"5\"\n\nvolumes:\n  caddy-data:\n  caddy-config:\n",
